DROP TRIGGER conc_rede_payment_recheck ON public.conc_rede_pagamentos;
CREATE TRIGGER conc_rede_payment_recheck AFTER UPDATE OR DELETE ON public.conc_rede_pagamentos FOR EACH ROW EXECUTE FUNCTION public.conc_recheck_composition_change();
CREATE TRIGGER conc_rede_adjustment_recheck AFTER UPDATE OR DELETE ON public.conc_rede_ajustes FOR EACH ROW EXECUTE FUNCTION public.conc_recheck_composition_change();
CREATE TRIGGER conc_rede_chargeback_recheck AFTER UPDATE OR DELETE ON public.conc_rede_chargebacks FOR EACH ROW EXECUTE FUNCTION public.conc_recheck_composition_change();
CREATE TRIGGER conc_rede_receipt_recheck AFTER UPDATE OF valor_depositado,data,bandeira,modalidade OR DELETE ON public.conc_rede_recebidos FOR EACH ROW EXECUTE FUNCTION public.conc_recheck_composition_change();
CREATE FUNCTION public.conc_bank_transit_details(p_hotel text,p_pending uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE p record;b record;typ text;matches jsonb;ops jsonb;candidates jsonb;BEGIN
IF auth.uid() IS NULL OR NOT public.can_access_conciliacao(auth.uid()) OR NOT public.can_view_hotel_data(auth.uid(),p_hotel) THEN RAISE EXCEPTION 'Sem permissão';END IF;
SELECT * INTO p FROM public.conc_pendencias WHERE id=p_pending AND hotel_id=p_hotel;IF NOT FOUND THEN RAISE EXCEPTION 'Pendência indisponível';END IF;
SELECT * INTO b FROM public.conc_bank_entries WHERE id=p.entry_id AND hotel_id=p_hotel;IF NOT FOUND THEN RETURN jsonb_build_object('cycle',to_jsonb(p),'reason','Lançamento bancário não disponível; histórico da pendência preservado','type','unknown','candidates','[]'::jsonb,'matches','[]'::jsonb,'opera','[]'::jsonb);END IF;
typ:=CASE WHEN public.conc_is_rede_bank(p_hotel,b.description) THEN 'rede' WHEN b.description ILIKE 'ZOOP%' THEN 'b2b' WHEN upper(public.unaccent_safe(b.description)) ~ '(BOLETO|COBRANCA|LIQUIDACAO)' THEN 'boleto' WHEN public.conc_is_financial_income(b.description) THEN 'income' WHEN public.conc_is_pix_bank(b.description) THEN 'pix' WHEN upper(public.unaccent_safe(b.description)) ~ '\m(DEP|DN|DIN|DINHEIRO|DEPOSITO)\M' THEN 'cash' ELSE 'unknown' END;
SELECT coalesce(jsonb_agg(to_jsonb(m)),'[]'::jsonb) INTO matches FROM public.conc_matches m WHERE m.hotel_id=p_hotel AND m.id IN(SELECT match_id FROM public.conc_match_items WHERE side='bank' AND entry_id=b.id);
SELECT coalesce(jsonb_agg(to_jsonb(o)),'[]'::jsonb) INTO ops FROM public.conc_opera_entries o WHERE o.hotel_id=p_hotel AND o.id IN(SELECT mi.entry_id FROM public.conc_match_items mi WHERE mi.side='opera' AND mi.match_id IN(SELECT match_id FROM public.conc_match_items WHERE side='bank' AND entry_id=b.id));
SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) INTO candidates FROM (
SELECT o.id,o.business_date date,o.amount,o.guest_full_name guest,o.room,o.receipt_no receipt,o.trx_desc category,o.matched_at FROM public.conc_opera_entries o WHERE o.hotel_id=p_hotel AND typ IN('pix','cash') AND o.base_conciliacao=CASE WHEN typ='pix' THEN 'PIX' ELSE 'DINHEIRO' END AND o.business_date BETWEEN b.line_date-1 AND b.line_date+1 AND NOT o.direct_bank ORDER BY abs(o.business_date-b.line_date),o.id LIMIT 200)x;
RETURN jsonb_build_object('cycle',to_jsonb(p),'bank',jsonb_build_object('id',b.id,'date',b.line_date,'description',b.description,'amount',b.amount,'account',b.account_name_raw,'matched_at',b.matched_at),'type',typ,'matches',matches,'opera',ops,'candidates',candidates,'reason',CASE WHEN p.status='revertida' THEN 'Este é um ciclo histórico revertido, não uma pendência atual.' WHEN b.matched_at IS NOT NULL THEN 'Banco confirmado; atualizar fechamento para conferir o ciclo.' WHEN typ='income' THEN CASE WHEN b.income_auto_excluded THEN 'Rendimento reaberto manualmente; nova baixa automática desabilitada.' ELSE 'Rendimento de aplicação: baixa como receita financeira, sem exigir venda no Ópera.' END WHEN typ='pix' THEN 'Crédito bancário sem vínculo confirmado. Confira os recebimentos PIX de D−1 a D+1; candidatos não representam conciliação.' WHEN typ='cash' THEN 'Depósito bancário sem vínculo confirmado. Confira a composição do caixa no Ópera; depósitos podem reunir mais de uma venda.' WHEN typ='unknown' THEN 'Crédito não classificado; transferência ou origem ainda sem comprovação. Não será baixado automaticamente.' ELSE 'Crédito sem composição bancária confirmada. Confira o relatório correspondente.' END);
END $$;
REVOKE ALL ON FUNCTION public.conc_bank_transit_details(text,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.conc_bank_transit_details(text,uuid) TO authenticated,service_role;